/* eslint-disable no-restricted-syntax, no-invalid-this */

'use strict';

// MODULES //

var logger = require( 'debug' );
var isObject = require( '@stdlib/assert/is-object' );
var setReadWriteAccessor = require( '@stdlib/utils/define-read-write-accessor' );
var setNonEnumerableReadOnly = require( '@stdlib/utils/define-nonenumerable-read-only-property' );
var setNonEnumerableReadOnlyAccessor = require( '@stdlib/utils/define-nonenumerable-read-only-accessor' ); // eslint-disable-line id-length
var hasProp = require( '@stdlib/assert/has-property' );
var inherit = require( '@stdlib/utils/inherit' );
var objectKeys = require( '@stdlib/utils/keys' );
var transformErrorMessage = require( '@stdlib/plot/vega/base/transform-validation-message' );
var instance2json = require( '@stdlib/plot/vega/base/to-json' );
var Mark = require( '@stdlib/plot/vega/mark/base/ctor' );
var format = require( '@stdlib/string/format' );
var properties = require( './properties.json' );
var defaults = require( './defaults.js' );

// Note: keep the following in alphabetical order according to the `require` path...
var getCornerRadius = require( './corner_radius/get.js' );
var setCornerRadius = require( './corner_radius/set.js' );

var getCornerRadiusBottomLeft = require( './corner_radius_bottom_left/get.js' );
var setCornerRadiusBottomLeft = require( './corner_radius_bottom_left/set.js' );

var getCornerRadiusBottomRight = require( './corner_radius_bottom_right/get.js' );
var setCornerRadiusBottomRight = require( './corner_radius_bottom_right/set.js' );

var getCornerRadiusTopLeft = require( './corner_radius_top_left/get.js' );
var setCornerRadiusTopLeft = require( './corner_radius_top_left/set.js' );

var getCornerRadiusTopRight = require( './corner_radius_top_right/get.js' );
var setCornerRadiusTopRight = require( './corner_radius_top_right/set.js' );

var getProperties = require( './properties/get.js' );

var getType = require( './type/get.js' );
var setType = require( './type/set.js' );

var TYPE = require( './type/type.js' );


// VARIABLES //

var debug = logger( 'vega:rect-mark:main' );


// MAIN //

/**
* Rect mark constructor.
*
* @constructor
* @param {Options} [options] - constructor options
* @param {boolean} [options.aria=true] - boolean indicating whether to include ARIA attributes in SVG output
* @param {(boolean|Signal|Object)} [options.clip=false] - setting indicating whether to clip marks to a specified shape
* @param {NonNegativeNumber} [options.cornerRadius=0] - radius in pixels of rounded rectangle corners for all four corners
* @param {NonNegativeNumber} [options.cornerRadiusTopLeft] - radius in pixels of rounded rectangle corner for the top left corner
* @param {NonNegativeNumber} [options.cornerRadiusTopRight] - radius in pixels of rounded rectangle corner for the top right corner
* @param {NonNegativeNumber} [options.cornerRadiusBottomLeft] - radius in pixels of rounded rectangle corner for the bottom left corner
* @param {NonNegativeNumber} [options.cornerRadiusBottomRight] - radius in pixels of rounded rectangle corner for the bottom right corner
* @param {string} [options.description] - text description of a mark for ARIA accessibility
* @param {Object} [options.encode] - object containing visual encoding rules for mark properties
* @param {Object} [options.from] - object describing the data a mark should visualize
* @param {boolean} [options.interactive=true] - boolean indicating whether a mark can serve as an input event source
* @param {(string|Object)} [options.key] - data field to use as a unique key for data binding
* @param {string} [options.name] - unique name
* @param {Array<Trigger>} [options.triggers=[]] - list of triggers for modifying mark properties in response to signal changes
* @param {Object} [options.sort] - comparator for sorting mark items
* @param {Array<Transform>} [options.transforms=[]] - list of post-encoding transforms to apply after any "encode" blocks and which operate directly on mark scenegraph items
* @param {string} [options.role] - metadata string indicating the role of a mark
* @param {(string|Array<string>)} [options.style] - custom styles to apply to a mark
* @param {number} [options.zindex=0] - integer z-index indicating the layering of a mark relative to other marks
* @throws {TypeError} options argument must be an object
* @throws {TypeError} `type` option, if provided, must be equal to "rect"
* @throws {Error} must provide valid options
* @returns {RectMark} rect mark instance
*
* @example
* var mark = new RectMark({
*     'cornerRadius': 5
* });
* // returns <RectMark>
*/
function RectMark( options ) {
	var opts;
	var keys;
	var v;
	var k;
	var i;
	if ( !( this instanceof RectMark ) ) {
		if ( arguments.length === 0 ) {
			return new RectMark( {} );
		}
		return new RectMark( options );
	}
	if ( arguments.length === 0 ) {
		options = {};
	}
	if ( !isObject( options ) ) {
		throw new TypeError( format( 'invalid argument. Options argument must be an object. Value: `%s`.', options ) );
	}
	if ( hasProp( options, 'type' ) && options.type !== TYPE ) {
		throw new TypeError( format( 'invalid argument. `%s` option must be equal to "%s". Option: `%s`.', 'type', TYPE, options.type ) );
	}
	options.type = TYPE;
	Mark.call( this, options );
	this._type = TYPE;

	// Resolve the default configuration:
	opts = defaults();

	// Set internal properties according to the default configuration...
	keys = objectKeys( opts );
	for ( i = 0; i < keys.length; i++ ) {
		k = keys[ i ];
		this[ '_'+k ] = opts[ k ];
	}
	// Validate provided options by attempting to assign option values to corresponding fields...
	for ( i = 0; i < properties.length; i++ ) {
		k = properties[ i ];
		if ( !hasProp( options, k ) ) {
			continue;
		}
		v = options[ k ];
		try {
			this[ k ] = v;
		} catch ( err ) {
			debug( 'Encountered an error. Error: %s', err.message );

			// FIXME: retain thrown error type
			throw new Error( transformErrorMessage( err.message ) );
		}
	}
	return this;
}

/*
* Inherit from a parent prototype.
*/
inherit( RectMark, Mark );

/**
* Constructor name.
*
* @private
* @name name
* @memberof RectMark
* @readonly
* @type {string}
*/
setNonEnumerableReadOnly( RectMark, 'name', 'RectMark' );

/**
* Radius in pixels of rounded rectangle corners for all four corners.
*
* @name cornerRadius
* @memberof RectMark.prototype
* @type {NonNegativeNumber}
* @default 0
*
* @example
* var mark = new RectMark({
*     'cornerRadius': 5
* });
*
* var v = mark.cornerRadius;
* // returns 5
*/
setReadWriteAccessor( RectMark.prototype, 'cornerRadius', getCornerRadius, setCornerRadius );

/**
* Radius in pixels of rounded rectangle corner for the bottom left corner.
*
* @name cornerRadiusBottomLeft
* @memberof RectMark.prototype
* @type {(NonNegativeNumber|void)}
*
* @example
* var mark = new RectMark({
*     'cornerRadiusBottomLeft': 3
* });
*
* var v = mark.cornerRadiusBottomLeft;
* // returns 3
*/
setReadWriteAccessor( RectMark.prototype, 'cornerRadiusBottomLeft', getCornerRadiusBottomLeft, setCornerRadiusBottomLeft );

/**
* Radius in pixels of rounded rectangle corner for the bottom right corner.
*
* @name cornerRadiusBottomRight
* @memberof RectMark.prototype
* @type {(NonNegativeNumber|void)}
*
* @example
* var mark = new RectMark({
*     'cornerRadiusBottomRight': 3
* });
*
* var v = mark.cornerRadiusBottomRight;
* // returns 3
*/
setReadWriteAccessor( RectMark.prototype, 'cornerRadiusBottomRight', getCornerRadiusBottomRight, setCornerRadiusBottomRight );

/**
* Radius in pixels of rounded rectangle corner for the top left corner.
*
* @name cornerRadiusTopLeft
* @memberof RectMark.prototype
* @type {(NonNegativeNumber|void)}
*
* @example
* var mark = new RectMark({
*     'cornerRadiusTopLeft': 3
* });
*
* var v = mark.cornerRadiusTopLeft;
* // returns 3
*/
setReadWriteAccessor( RectMark.prototype, 'cornerRadiusTopLeft', getCornerRadiusTopLeft, setCornerRadiusTopLeft );

/**
* Radius in pixels of rounded rectangle corner for the top right corner.
*
* @name cornerRadiusTopRight
* @memberof RectMark.prototype
* @type {(NonNegativeNumber|void)}
*
* @example
* var mark = new RectMark({
*     'cornerRadiusTopRight': 3
* });
*
* var v = mark.cornerRadiusTopRight;
* // returns 3
*/
setReadWriteAccessor( RectMark.prototype, 'cornerRadiusTopRight', getCornerRadiusTopRight, setCornerRadiusTopRight );

/**
* Mark properties.
*
* @name properties
* @memberof RectMark.prototype
* @type {Array<string>}
*
* @example
* var mark = new RectMark({});
*
* var v = mark.properties;
* // returns [...]
*/
setNonEnumerableReadOnlyAccessor( RectMark.prototype, 'properties', getProperties );

/**
* Mark type.
*
* @name type
* @memberof RectMark.prototype
* @type {string}
* @default 'rect'
*
* @example
* var mark = new RectMark({
*     'cornerRadius': 5
* });
*
* var v = mark.type;
* // returns 'rect'
*/
setReadWriteAccessor( RectMark.prototype, 'type', getType, setType );

/**
* Serializes an instance to a JSON object.
*
* ## Notes
*
* -   This method is implicitly invoked by `JSON.stringify`.
*
* @name toJSON
* @memberof RectMark.prototype
* @type {Function}
* @returns {Object} JSON object
*
* @example
* var mark = new RectMark({
*     'cornerRadius': 5
* });
*
* var v = mark.toJSON();
* // returns {...}
*/
setNonEnumerableReadOnly( RectMark.prototype, 'toJSON', function toJSON() {
	return instance2json( this, properties );
});


// EXPORTS //

module.exports = RectMark;
